import java.util.*;

// ABM de transportistas (alta, baja, modificación). Datos INVENTADOS. Sin interfaz gráfica.
public class Abm {
    record Transportista(int id, String nombre, String zona, boolean activo, int version) {}

    static class Repositorio {
        private final Map<Integer, Transportista> filas = new TreeMap<>();
        private int proximo = 1;

        Transportista alta(String nombre, String zona) {
            if (nombre == null || nombre.isBlank()) throw new IllegalArgumentException("El nombre es obligatorio");
            var t = new Transportista(proximo++, nombre.trim(), zona, true, 1);
            filas.put(t.id(), t);
            return t;
        }
        Transportista modificar(int id, String nombre, int versionQueVi) {
            var actual = filas.get(id);
            if (actual == null) throw new NoSuchElementException("No existe el id " + id);
            if (actual.version() != versionQueVi)
                throw new IllegalStateException("Alguien modificó el registro: viste v" + versionQueVi + " y ahora es v" + actual.version());
            var nuevo = new Transportista(id, nombre, actual.zona(), actual.activo(), actual.version() + 1);
            filas.put(id, nuevo);
            return nuevo;
        }
        void baja(int id) {                       // baja LÓGICA: el registro queda, marcado como inactivo
            var a = filas.get(id);
            filas.put(id, new Transportista(id, a.nombre(), a.zona(), false, a.version() + 1));
        }
        Collection<Transportista> todos() { return filas.values(); }
    }

    static void pantalla(String titulo, Repositorio r) {
        System.out.println("== " + titulo);
        System.out.printf("%-3s %-18s %-8s %-7s %s%n", "ID", "NOMBRE", "ZONA", "ESTADO", "v");
        for (var t : r.todos())
            System.out.printf("%-3d %-18s %-8s %-7s %d%n", t.id(), t.nombre(), t.zona(), t.activo() ? "activo" : "baja", t.version());
    }

    public static void main(String[] args) {
        var repo = new Repositorio();
        repo.alta("Fletes Ejemplo SA", "AMBA");
        repo.alta("Camiones del Sur", "Sur");
        pantalla("Después de dos altas", repo);

        repo.modificar(1, "Fletes Ejemplo SRL", 1);
        repo.baja(2);
        pantalla("Después de modificar el 1 y dar de baja el 2", repo);

        try { repo.alta("   ", "AMBA"); } catch (IllegalArgumentException e) { System.out.println("Rechazado: " + e.getMessage()); }
        try { repo.modificar(1, "Otro nombre", 1); } catch (IllegalStateException e) { System.out.println("Rechazado: " + e.getMessage()); }
    }
}

