record Transportista(int Id, string Nombre, string Zona, bool Activo, int Version);

class Repositorio
{
    private readonly SortedDictionary<int, Transportista> _filas = new();
    private int _proximo = 1;

    public Transportista Alta(string nombre, string zona)
    {
        if (string.IsNullOrWhiteSpace(nombre)) throw new ArgumentException("El nombre es obligatorio");
        var t = new Transportista(_proximo++, nombre.Trim(), zona, true, 1);
        _filas[t.Id] = t;
        return t;
    }

    public Transportista Modificar(int id, string nombre, int versionQueVi)
    {
        if (!_filas.TryGetValue(id, out var actual)) throw new KeyNotFoundException($"No existe el id {id}");
        if (actual.Version != versionQueVi)
            throw new InvalidOperationException($"Alguien modificó el registro: viste v{versionQueVi} y ahora es v{actual.Version}");
        var nuevo = actual with { Nombre = nombre, Version = actual.Version + 1 };
        _filas[id] = nuevo;
        return nuevo;
    }

    public void Baja(int id)   // baja LÓGICA: el registro queda, marcado como inactivo
        => _filas[id] = _filas[id] with { Activo = false, Version = _filas[id].Version + 1 };

    public IEnumerable<Transportista> Todos() => _filas.Values;
}
